'use strict';
const EmployeeIdentity={
 name(user){return I18n.language==='en'?(user.display_name_en||I18n.translate(user.display_name,true)):user.display_name;},
 role(user){return I18n.language==='en'?(user.role_name_en||I18n.translate(Accounts.names[user.role_code]||user.role_name||'历史角色',true)):(user.role_name||Accounts.names[user.role_code]||'历史角色');},
 refresh(){if(!window.CurrentUser)return;const full=this.name(CurrentUser)+' / '+this.role(CurrentUser);for(const el of [document.getElementById('signed-user'),document.querySelector('.snapshot')])if(el){el.setAttribute('data-no-i18n','');el.textContent=full;}const footer=document.querySelector('.sidebar-bottom');if(footer){footer.setAttribute('data-no-i18n','');footer.replaceChildren();const version=document.createElement('div');version.className='system-version';version.textContent=I18n.translate('系统版本',true)+(I18n.language==='en'?' ':'')+'V'+(AppConfig.version||ClientRelease.version);const copyright=document.createElement('div');copyright.className='copyright-notice sidebar-copyright';copyright.textContent=I18n.language==='en'?'© 2026 Tang Lei · All rights reserved.':'© 2026 唐雷 · 保留所有权利';footer.append(version,copyright);}const avatar=document.querySelector('.avatar');if(avatar){avatar.setAttribute('data-no-i18n','');avatar.textContent=this.name(CurrentUser).slice(0,1);}for(const el of document.querySelectorAll('[data-employee-id]')){const user=Accounts.users?.find(u=>u.id===el.dataset.employeeId);if(user)el.textContent=this.name(user);}}
};
const identityLanguage=I18n.set.bind(I18n);I18n.set=function(language){identityLanguage(language);EmployeeIdentity.refresh();};EmployeeIdentity.refresh();
